1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	}
66	
67	const ITEM_SPECS = {
68	  sword: { basePremium: 100, insuranceValue: 1000 },
69	  amulet: { basePremium: 60, insuranceValue: 600 },
70	  staff: { basePremium: 80, insuranceValue: 800 },
71	  potion: { basePremium: 40, insuranceValue: 400 },
72	  rune: { basePremium: 25, insuranceValue: 250 },
73	  moonstone: { basePremium: 25, insuranceValue: 250 },
74	} as const satisfies Record<string, ItemSpec>;
75	
76	type KnownItemType = keyof typeof ITEM_SPECS;
77	
78	const isKnownItemType = (type: string): type is KnownItemType =>
79	  type in ITEM_SPECS;
80	
81	// The office insures only what its price list names. An unknown type has no
82	// premium and no insurance value, so there is nothing to quote — the whole
83	// scenario is rejected rather than priced at zero.
84	const specForItem = (item: Item): ItemSpec => {
85	  if (!isKnownItemType(item.type)) {
86	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
87	  }
88	  return ITEM_SPECS[item.type];
89	};
90	
91	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
92	
93	const BLOCK_SIZE = 3;
94	
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	const sum = (amounts: number[]): number =>
98	  amounts.reduce((total, amount) => total + amount, 0);
99	
100	// "Alike" means the same exact type, not merely the same family: two runes and
101	// a moonstone are three components but not three alike ones, so grouping them
102	// by type keeps them apart and denies them the block price.
103	const groupByType = (items: Item[]): Item[][] => {
104	  const groups = new Map<string, Item[]>();
105	  for (const item of items) {
106	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
107	  }
108	  return [...groups.values()];
109	};
110	
111	// A block is not carved out of a larger group: the block price applies only
112	// when the group consists of exactly three alike components (7 runes cost
113	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
114	// ever passes a single group from groupByType.
115	const basePremiumForGroup = (group: Item[]): number =>
116	  group.length === BLOCK_SIZE
117	    ? BLOCK_BASE_PREMIUM
118	    : sum(group.map(basePremiumForItem));
119	
120	const basePremiumForItems = (items: Item[]): number =>
121	  sum(groupByType(items).map(basePremiumForGroup));
122	
123	const CURSE_SURCHARGE = 0.5;
124	
125	// Every modifier is an additive percentage of its OWN base — modifiers never
126	// compound with each other. Item-scoped modifiers take the affected item's base
127	// premium as their base; policy-scoped modifiers take the policy base premium
128	// (the sum of all item base premiums). So the total is always
129	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
130	const modifierAmount = (rate: number, base: number): number => rate * base;
131	
132	const ENCHANTMENT_SURCHARGE = 0.3;
133	
134	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
135	
136	const isCursed = (item: Item): boolean => item.cursed === true;
137	
138	const attractsEnchantmentSurcharge = (item: Item): boolean =>
139	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
140	
141	interface ItemModifier {
142	  rate: number;
143	  appliesTo: (item: Item) => boolean;
144	}
145	
146	// Each item-scoped modifier is a row: a rate and the condition under which it
147	// applies. The predicate names the modifier, so a row needs no separate label.
148	// Adding a modifier means adding a row, not a new branch.
149	const ITEM_MODIFIERS: ItemModifier[] = [
150	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
151	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
152	];
153	
154	const itemModifierRates = (item: Item): number[] =>
155	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
156	    (modifier) => modifier.rate,
157	  );
158	
159	const LOYALTY_DISCOUNT = 0.2;
160	
161	const LOYALTY_THRESHOLD_YEARS = 2;
162	
163	const isLongStanding = (customer: Customer): boolean =>
164	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
165	
166	// Discounts are surcharges with the sign flipped: expressing one as a negative
167	// rate lets it flow through the same additive sum as every surcharge, with no
168	// separate subtraction step. Discount constants stay positive magnitudes and
169	// are negated here, at the point of use, so the direction is visible in the
170	// rate list rather than buried in a constant's sign.
171	const asDiscount = (rate: number): number => -rate;
172	
173	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
174	
175	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
176	
177	// Policy-scoped modifiers apply to the policy base premium. Unlike item
178	// modifiers they select on the customer and on the quote's position in the
179	// scenario rather than on an item.
180	//
181	// The initial-assessment surcharge applies to every quote: each item is treated
182	// as a first insurance regardless of customer history. The follow-up discount
183	// is what distinguishes a customer's later contracts.
184	const policyModifierRates = (
185	  customer: Customer,
186	  isFollowUpContract: boolean,
187	): number[] => [
188	  INITIAL_ASSESSMENT_SURCHARGE,
189	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
190	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
191	];
192	
193	const itemModifiersTotal = (items: Item[]): number =>
194	  sum(
195	    items.flatMap((item) =>
196	      itemModifierRates(item).map((rate) =>
197	        modifierAmount(rate, basePremiumForItem(item)),
198	      ),
199	    ),
200	  );
201	
202	const policyModifiersTotal = (
203	  policyBasePremium: number,
204	  customer: Customer,
205	  isFollowUpContract: boolean,
206	): number =>
207	  sum(
208	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
209	      modifierAmount(rate, policyBasePremium),
210	    ),
211	  );
212	
213	// All amounts are rounded to whole G in the MHPCO's favour. Which way that
214	// points depends on which way the money flows: a premium comes in, so it rounds
215	// up; a payout goes out, so it rounds down. Two functions rather than one with a
216	// direction flag, because each names a rule rather than a parameter.
217	const roundPremiumInMHPCOsFavour = (amount: number): number =>
218	  Math.ceil(amount);
219	
220	const roundPayoutInMHPCOsFavour = (amount: number): number =>
221	  Math.floor(amount);
222	
223	const quotePremium = (
224	  items: Item[],
225	  customer: Customer,
226	  isFollowUpContract: boolean,
227	): number => {
228	  const policyBasePremium = basePremiumForItems(items);
229	  return roundPremiumInMHPCOsFavour(
230	    policyBasePremium +
231	      itemModifiersTotal(items) +
232	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
233	      PROCESSING_FEE,
234	  );
235	};
236	
237	const insuranceValueForItem = (item: Item): number =>
238	  specForItem(item).insuranceValue;
239	
240	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
241	// figure from ITEM_SPECS, but the premium side groups by type first so a block
242	// of three alike components can be priced as one; this side never groups. Three
243	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
244	// discount on the price of cover, not a reduction of the cover bought.
245	//
246	// So the near-symmetry is a false friend: factoring the two into one traversal
247	// would read as tidier and would silently make blocks shrink the insurance sum.
248	// The repetition of `sum(items.map(...))` is the price of keeping them free to
249	// diverge, and is paid on purpose.
250	const insuranceSum = (items: Item[]): number =>
251	  sum(items.map(insuranceValueForItem));
252	
253	const CAP_MULTIPLE = 2;
254	
255	// The cap is twice the insurance sum — the value the items are insured FOR, so
256	// it is computed from the items alone and never from the premium. Curses,
257	// enchantments and loyalty change what a policy costs without changing what it
258	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
259	// separation visible at the one place a policy is created.
260	const capForItems = (items: Item[]): number =>
261	  CAP_MULTIPLE * insuranceSum(items);
262	
263	const DEDUCTIBLE = 100;
264	
265	interface Policy {
266	  items: Item[];
267	  remainingCap: number;
268	}
269	
270	// Steps are not independent: a quote's premium depends on how many quotes came
271	// before it, and a claim draws down the cap of a policy an earlier quote
272	// created. So a step is a function from state to (result, next state), and the
273	// scenario is a fold over that — not a map, which would promise an independence
274	// the steps do not have.
275	//
276	// Policies are keyed by the index of the quote step that created them: a claim
277	// step names its policy by that zero-based index.
278	interface ScenarioState {
279	  quotesSoFar: number;
280	  policies: Map<number, Policy>;
281	}
282	
283	const INITIAL_STATE: ScenarioState = {
284	  quotesSoFar: 0,
285	  policies: new Map(),
286	};
287	
288	interface StepOutcome {
289	  result: StepResult;
290	  state: ScenarioState;
291	}
292	
293	// Both operations end by filing a policy under its quote's index — a claim
294	// re-files the same policy with a drawn-down cap. Naming that once keeps the
295	// Map out of the operations, so neither has to know how policies are stored.
296	const withPolicy = (
297	  state: ScenarioState,
298	  policyIndex: number,
299	  policy: Policy,
300	): ScenarioState => ({
301	  ...state,
302	  policies: new Map(state.policies).set(policyIndex, policy),
303	});
304	
305	const runQuote = (
306	  step: QuoteStep,
307	  customer: Customer,
308	  state: ScenarioState,
309	  stepIndex: number,
310	): StepOutcome => ({
311	  result: {
312	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
313	  },
314	  state: withPolicy(
315	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
316	    stepIndex,
317	    {
318	      items: step.items,
319	      remainingCap: capForItems(step.items),
320	    },
321	  ),
322	});
323	
324	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
325	
326	const REDUCED_REIMBURSEMENT_RATE = 0.5;
327	
328	const FULL_REIMBURSEMENT_RATE = 1;
329	
330	// Reads enchantment like the premium-side surcharge rule, but is a different
331	// rule with its own level: this one halves what a claim pays out, that one
332	// raises what a policy costs. Sharing a predicate would tie two levels that the
333	// spec lets move independently, so the shape is repeated deliberately.
334	const qualifiesForReducedReimbursement = (item: Item): boolean =>
335	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
336	
337	// The reimbursement rate is decided first, then one deductible comes off.
338	//
339	// The dragon-material clause is absent on purpose, not by oversight. It promises
340	// full reimbursement of the damage before the deductible — which is exactly what
341	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
342	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
343	// them the two facts leave the clause with no input it can move: dragon material
344	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
345	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
346	// would add a branch no test could ever tell from the default — a distinction
347	// the domain does not make.
348	const reimbursementRate = (item: Item): number =>
349	  qualifiesForReducedReimbursement(item)
350	    ? REDUCED_REIMBURSEMENT_RATE
351	    : FULL_REIMBURSEMENT_RATE;
352	
353	const payoutForDamage = (damage: Damage, item: Item): number =>
354	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
355	
356	// Returns AN insured item of the damaged type, not THE damaged one — a policy
357	// can cover two swords, so the type does not name a unique item. Two damage
358	// entries of the same type are both answered with the same first match.
359	//
360	// That is sound today because the answer is used solely to read payout
361	// attributes (the reimbursement rate), and the covered case — two damages
362	// against two swords — insures identical swords, which read the same either
363	// way. The deductible is charged per damage entry, not per matched item, so
364	// counting is unaffected too.
365	//
366	// One thing would break it, not yet under test: two swords with DIFFERENT
367	// attributes (say enchantment 3 and 9). Both damages would take the first
368	// sword's rate; the second should take its own. This lookup must then become a
369	// pairing that consumes what it matches. The honest name marks that spot.
370	//
371	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
372	// throws unless every claimed type is covered at least as many times as it is
373	// named — so by the time this runs, a match exists for every damage entry. Both
374	// ways it could fail are covered by tests: claiming a type more often than it is
375	// insured, and claiming a type the policy does not cover at all.
376	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
377	  policy.items.find((item) => item.type === damage.itemType)!;
378	
379	// Counts how many times each value occurs. Deliberately typed on strings rather
380	// than on Item: the guard below tallies two different things (item types held
381	// and item types named by damages) and only their counts are ever compared, so
382	// the tally has no business knowing what the strings mean.
383	const tally = (values: string[]): Map<string, number> => {
384	  const counts = new Map<string, number>();
385	  for (const value of values) {
386	    counts.set(value, (counts.get(value) ?? 0) + 1);
387	  }
388	  return counts;
389	};
390	
391	// Every damage entry must claim an insured item of its own, so a type cannot be
392	// damaged more times than the policy covers it. One rule, two error cases the
393	// spec states separately: claiming a type more often than it is insured, and
394	// claiming a type the policy does not cover at all. The second is the first at
395	// zero — an uninsured type is covered 0 times against a claimed 1 — so both are
396	// caught by the same comparison rather than by a separate membership test.
397	//
398	// Checked before any payout is computed: the spec rejects the whole claim, not
399	// just the surplus entries.
400	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
401	  const insured = tally(policy.items.map((item) => item.type));
402	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
403	  for (const [type, claimedCount] of claimed) {
404	    const insuredCount = insured.get(type) ?? 0;
405	    if (claimedCount > insuredCount) {
406	      throw new Error(
407	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
408	      );
409	    }
410	  }
411	};
412	
413	// A damage is what an incident cost the owner, so it cannot be negative. Zero
414	// is left alone: the spec forbids only negative amounts, and a zero damage
415	// simply pays nothing once the deductible bites.
416	const isNegative = (damage: Damage): boolean => damage.amount < 0;
417	
418	const rejectNegativeDamages = (incident: Incident): void => {
419	  const negative = incident.damages.find(isNegative);
420	  if (negative) {
421	    throw new Error(
422	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
423	    );
424	  }
425	};
426	
427	// Both guards run before any payout is computed: the spec rejects the whole
428	// claim, not just the offending entries, so a valid entry alongside an invalid
429	// one must not be paid.
430	//
431	// They are two statements rather than a list of validations. Their signatures
432	// differ (only the first needs the policy), so a uniform list could hold them
433	// only by giving the second a parameter it ignores. And the order is not
434	// incidental: rejectUnmatchedDamages must come first because it is what makes
435	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
436	// a sequenced line here but would vanish into array order in a list. The third
437	// validation the spec calls for (unknown item type) belongs to the quote path,
438	// so this pair is closed at two and has no growth to abstract over.
439	const payoutForIncident = (policy: Policy, incident: Incident): number => {
440	  rejectUnmatchedDamages(policy, incident);
441	  rejectNegativeDamages(incident);
442	  return sum(
443	    incident.damages.map((damage) =>
444	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
445	    ),
446	  );
447	};
448	
449	// The damage decides what a claim is WORTH; the cap decides what there is left
450	// to pay it WITH. Once the cap is spent the office pays what remains, not what
451	// was asked — so the cap bounds the payout before it is charged against it.
452	//
453	// This is the guarantee that makes drawDownCap's subtraction safe: a payout that
454	// has passed through here can never exceed the balance, so the balance can never
455	// go negative. The two are a pair — bound, then spend — and neither is sound
456	// without the other.
457	const payoutWithinCap = (payout: number, remainingCap: number): number =>
458	  Math.min(payout, remainingCap);
459	
460	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
461	// it and the rest carries forward to the next claim against the same policy.
462	// The balance stays non-negative because payoutWithinCap has already bounded
463	// what is spent — this subtraction does not defend itself, it relies on that.
464	//
465	// Naming the draw-down separates what the cap DOES from how a claim is assembled
466	// — the one line in runClaim that was arithmetic rather than plumbing.
467	const drawDownCap = (remainingCap: number, payout: number): number =>
468	  remainingCap - payout;
469	
470	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
471	  // A claim naming a policy that does not exist is a spec error case, but no
472	  // test drives it yet. The assertion stands in until one does — at which point
473	  // the missing case becomes the error branch rather than a crash.
474	  const policy = state.policies.get(step.policy)!;
475	  // Rounded before the clamp so the cap is only ever compared with, and reduced
476	  // by, whole G — a fractional payout would otherwise leave a fractional cap
477	  // behind for the next claim.
478	  const payout = payoutWithinCap(
479	    roundPayoutInMHPCOsFavour(payoutForIncident(policy, step.incident)),
480	    policy.remainingCap,
481	  );
482	  const remainingCap = drawDownCap(policy.remainingCap, payout);
483	  return {
484	    result: { payout, remainingCap },
485	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
486	  };
487	};
488	
489	// Dispatch decides once what a step is; each operation then owns both its
490	// result and how it advances the state, so no caller has to re-test step.op to
491	// know what the step did.
492	const runStep = (
493	  step: Step,
494	  customer: Customer,
495	  state: ScenarioState,
496	  stepIndex: number,
497	): StepOutcome =>
498	  step.op === "quote"
499	    ? runQuote(step, customer, state, stepIndex)
500	    : runClaim(step, state);
501	
502	// The fold carries both halves of the outcome: the results accumulated so far
503	// and the state the next step will see. Threading the state explicitly (rather
504	// than recovering it from the last result) keeps the dependency between steps
505	// visible in the type.
506	interface ScenarioRun {
507	  results: StepResult[];
508	  state: ScenarioState;
509	}
510	
511	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
512	
513	const appendStep =
514	  (customer: Customer) =>
515	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
516	    const outcome = runStep(step, customer, run.state, stepIndex);
517	    return {
518	      results: [...run.results, outcome.result],
519	      state: outcome.state,
520	    };
521	  };
522	
523	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
524	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
525	});
